
-- Batch 9: Libya through Nigeria (NG codes) + Madagascar, Malawi, Mali, Morocco, Mozambique, Mexico
UPDATE recipes SET continent = 'Africa', history = 'Bazeen is Libya''s traditional dish of unleavened barley dough served with a spiced lamb or chicken stew. This ancient dish represents the Berber and Arab culinary traditions of North Africa and has been a staple of Libyan hospitality for centuries, typically shared from a communal platter.' WHERE slug = 'bazeen-libya';

UPDATE recipes SET continent = 'Africa', history = 'Moroccan Carrot Salad is a vibrant mezze dish showcasing Morocco''s mastery of spices. Cumin, paprika, and preserved lemon transform humble carrots into an exotic, aromatic salad. This dish exemplifies the Moroccan philosophy that even the simplest vegetables deserve royal treatment.' WHERE slug = 'moroccan-carrot-ma';

UPDATE recipes SET continent = 'Africa', history = 'Lasary Voatabia is a Malagasy tomato condiment that accompanies rice, the staple of every Malagasy meal. Madagascar''s cuisine reflects its Southeast Asian (Indonesian) origins blended with African and French influences. This fresh relish represents the island''s unique position in culinary geography.' WHERE slug = 'lasary-voatabia-madagascar';

UPDATE recipes SET continent = 'Africa', history = 'Ravitoto sy Henakisoa is Madagascar''s beloved dish of pounded cassava leaves cooked with pork. This hearty stew reflects the island''s mixed Southeast Asian and African culinary heritage. Cassava, introduced from South America, became central to Malagasy cuisine and represents the island''s agricultural adaptability.' WHERE slug = 'ravitoto-sy-henakisoa-madagascar';

UPDATE recipes SET continent = 'Africa', history = 'Chambo ya Kuuka is a Malawian smoked fish dish featuring chambo, a type of tilapia endemic to Lake Malawi. The smoking and drying of fish from Lake Malawi has sustained local communities for centuries. Chambo is Malawi''s most prized fish and a symbol of the country''s lake-based food traditions.' WHERE slug = 'chambo-ya-kuuka-malawi';

UPDATE recipes SET continent = 'Africa', history = 'Mbatata (Sweet Potato Cookies) from Malawi showcase the versatility of sweet potatoes in Southern African baking. Sweet potatoes, introduced from the Americas, became a staple crop in Malawi. These cookies represent the creative adaptation of Western baking techniques with local African ingredients.' WHERE slug = 'mbatata-sweet-potato-cookies-malawi';

UPDATE recipes SET continent = 'Africa', history = 'Bambara Groundnut Soup represents one of Africa''s oldest cultivated legumes. The Bambara groundnut, indigenous to West Africa, has been grown in Mali and across the Sahel for thousands of years. This protein-rich soup is a testament to Africa''s ancient agricultural innovations and indigenous crops.' WHERE slug = 'bambara-groundnut-soup';

UPDATE recipes SET continent = 'Africa', history = 'Dholl Puri with Cari Gros Pois is Mauritius''s most popular street food, reflecting the island''s Indian diaspora heritage. This flatbread filled with ground yellow split peas served with bean curry represents the Indo-Mauritian culinary tradition that has become central to Mauritian national identity.' WHERE slug = 'dholl-puri-cari-gros-pois-mauritius';

UPDATE recipes SET continent = 'North America', history = 'Chicken Enchiladas are a cornerstone of Mexican cuisine, with roots in the Aztec practice of rolling tortillas around fillings. The word "enchilada" means "seasoned with chili." This dish represents Mexico''s rich pre-Columbian culinary heritage that survived and evolved through the colonial era.' WHERE slug = 'chicken-enchiladas';

UPDATE recipes SET continent = 'Africa', history = 'Maafe (Groundnut Stew) is Mali''s beloved peanut-based stew, central to Mandinka culinary traditions across West Africa. Groundnuts, introduced from the Americas in the 16th century, quickly became essential to Sahelian cuisine. Maafe represents the creative genius of West African one-pot cooking.' WHERE slug = 'maafe-ml';

UPDATE recipes SET continent = 'Africa', history = 'Bissara (Fava Bean Soup) is a traditional Moroccan soup served especially during cold months and Ramadan. Fava beans have been cultivated in Morocco since ancient times, and this warming soup, seasoned with cumin and olive oil, represents the comforting, nourishing side of Moroccan cuisine.' WHERE slug = 'bissara-fava-bean-soup-morocco';

UPDATE recipes SET continent = 'Africa', history = 'Rfalfouza is a traditional Moroccan almond-orange semolina cake that showcases the country''s renowned pastry traditions. Moroccan baking combines Berber, Arab, and Andalusian influences, using almonds, orange blossom water, and semolina to create elegant desserts served at celebrations and with mint tea.' WHERE slug = 'rfalfouza-almond-orange-cake-morocco';

UPDATE recipes SET continent = 'Africa', history = 'Rfissa (Trid with Chicken) is a traditional Moroccan dish served to new mothers and at celebrations. Layers of hand-stretched msemen bread are steamed with a lentil and chicken stew spiced with fenugreek. This ceremonial dish represents Moroccan beliefs about food as medicine and nourishment.' WHERE slug = 'rfissa-trid-chicken-morocco';

UPDATE recipes SET continent = 'Africa', history = 'Galinha à Zambeziana is a Mozambican chicken dish from the Zambezia province, featuring coconut milk and piri piri chili. This dish exemplifies the Portuguese-African culinary fusion that defines Mozambican cuisine, combining European cooking techniques with indigenous African ingredients and flavors.' WHERE slug = 'galinha-a-zambeziana-mozambique';

UPDATE recipes SET continent = 'North America', history = 'Churros originated in Spain or Portugal and were brought to Mexico by Spanish colonizers. Mexican churros, rolled in cinnamon sugar and served with chocolate sauce, became a beloved street food across Latin America. This sweet treat represents the delicious culinary legacy of Spanish colonialism in the Americas.' WHERE slug = 'churros-mx';

UPDATE recipes SET continent = 'North America', history = 'Elote (Mexican Street Corn) is one of Mexico''s most iconic street foods. Corn has been sacred to Mexican culture for over 7,000 years since its domestication by ancient Mesoamerican peoples. Grilled and slathered with mayo, chili powder, and cotija cheese, elote celebrates Mexico''s ancestral grain.' WHERE slug = 'elote-mx';

UPDATE recipes SET continent = 'North America', history = 'Horchata is a refreshing rice milk beverage brought to Mexico by Spanish colonizers, who adapted it from the original Valencian version made with tiger nuts. Mexican horchata, flavored with cinnamon and vanilla, has become one of the country''s most beloved aguas frescas and is now popular globally.' WHERE slug = 'horchata-mx';

UPDATE recipes SET continent = 'North America', history = 'Tacos al Pastor were created in 1930s-1960s central Mexico by Lebanese immigrants who adapted their shawarma technique. Instead of lamb on a vertical spit, Mexican taqueros used marinated pork with chilies and pineapple. This dish is one of the most successful culinary fusions in world history.' WHERE slug = 'tacos-al-pastor-mx';

UPDATE recipes SET continent = 'Africa', history = 'Kapana is Namibia''s beloved street food of grilled meat sold at open-air markets. Originating in the townships, kapana has become a national food tradition where vendors grill beef over open fires and serve it with chili sauce. It represents the vibrant, communal street food culture of modern Namibia.' WHERE slug = 'kapana-namibia';

UPDATE recipes SET continent = 'Africa', history = 'Abacha (African Salad) is a traditional Igbo dish from eastern Nigeria made from dried shredded cassava mixed with palm oil, ugba (oil bean), and vegetables. This unique salad-like preparation represents the sophisticated culinary traditions of the Igbo people and is a must-have at celebrations.' WHERE slug = 'abacha-ng';

UPDATE recipes SET continent = 'Africa', history = 'Abacha with Ugba is the classic Igbo pairing of cassava flakes with fermented oil bean seed, a combination beloved across southeastern Nigeria. This dish represents the ancient Igbo tradition of fermentation and preservation, creating complex umami flavors from indigenous plant ingredients.' WHERE slug = 'abacha-ugba-ng';

UPDATE recipes SET continent = 'Africa', history = 'Achara (Pickled Vegetables) is a Nigerian pickle tradition, showing the influence of Southeast Asian preservation techniques that traveled via trade routes. In Nigeria, achara features green papaya and peppers, providing a tangy accompaniment to rich dishes. It represents Nigeria''s absorptive culinary culture.' WHERE slug = 'achara-ng';

UPDATE recipes SET continent = 'Africa', history = 'Banga Soup is a beloved palm fruit soup from the Niger Delta region of Nigeria, made from fresh palm fruits. This rich, aromatic soup, typically served with starch or pounded yam, represents the culinary traditions of the Urhobo, Itsekiri, and other Delta peoples who have harvested palm fruits for centuries.' WHERE slug = 'banga-soup-ng';

UPDATE recipes SET continent = 'Africa', history = 'Chin Chin are crispy fried dough snacks essential to every Nigerian celebration. These addictive, slightly sweet bites are made during Christmas, weddings, and naming ceremonies. Each family has their own recipe, passed through generations, making chin chin a deeply personal part of Nigerian food culture.' WHERE slug = 'chin-chin-ng';

UPDATE recipes SET continent = 'Africa', history = 'Egusi Soup is one of Nigeria''s most popular soups, made from ground melon seeds cooked with leafy vegetables, palm oil, and assorted proteins. Melon seeds have been cultivated in West Africa for thousands of years, and this nutritious, protein-rich soup is a daily staple across Nigeria.' WHERE slug = 'egusi-soup-ng';
